+
+bool ModuleManager::virtualSurroundSupported() const
+{
+    return Context::instance()->server()->isPipeWire() && !virtualSurroundHrtfPath().isEmpty();
+}
+
+bool ModuleManager::virtualSurround() const
+{
+    return QFile::exists(virtualSurroundConfigPath());
+}
+
+void ModuleManager::setVirtualSurround(bool virtualSurround)
+{
+    if (m_virtualSurroundBusy || virtualSurround == this->virtualSurround()) {
+        return;
+    }
+
+    m_virtualSurroundError.clear();
+    if (!writeVirtualSurroundConfig(virtualSurround)) {
+        Q_EMIT virtualSurroundChanged();
+        return;
+    }
+    m_virtualSurroundBusy = true;
+    Q_EMIT virtualSurroundChanged();
+
+    // PipeWire only reads its configuration on startup
+    AudioServices::restart(this, [this, virtualSurround](const QString &error) {
+        if (!error.isEmpty()) {
+            writeVirtualSurroundConfig(!virtualSurround);
+            finishVirtualSurround(error);
+        } else if (virtualSurround) {
+            waitForVirtualSurroundSink();
+        } else {
+            finishVirtualSurround(QString());
+        }
+    });
+}
+
+bool ModuleManager::writeVirtualSurroundConfig(bool virtualSurround)
+{
+    const QString path = virtualSurroundConfigPath();
+    if (!virtualSurround) {
+        if (!QFile::remove(path) && QFile::exists(path)) {
+            qCWarning(PLASMAPA) << "Failed to remove" << path;
+            m_virtualSurroundError = i18nc("@info error %1 is a path", "Failed to remove file: %1.", path);
+            return false;
+        }
+        return true;
+    }
+
+    const QString dir = QFileInfo(path).path();
+    if (!QDir().mkpath(dir)) {
+        qCWarning(PLASMAPA) << "Failed to create" << dir;
+        m_virtualSurroundError = i18nc("@info error %1 is a path", "Failed to create directory: %1.", dir);
+        return false;
+    }
+    QFile file(path);
+    if (!file.open(QFile::WriteOnly | QFile::Truncate) || file.write(virtualSurroundConfig()) == -1) {
+        qCWarning(PLASMAPA) << "Failed to write" << path << file.errorString();
+        file.remove();
+        m_virtualSurroundError = i18nc("@info error %1 is a path", "Failed to open file for writing: %1.", path);
+        return false;
+    }
+    return true;
+}
+
+void ModuleManager::waitForVirtualSurroundSink()
+{
+    // The filter-chain module is loaded with nofail, so PipeWire starts fine without the sink when the
+    // filter can't be created, for example when PipeWire's sofa plugin is not installed.
+    auto hasSink = [] {
+        const auto sinks = Context::instance()->sinks();
+        return std::any_of(sinks.cbegin(), sinks.cend(), [](Sink *sink) {
+            return sink->name() == virtualSurroundSinkName;
+        });
+    };
+    if (hasSink()) {
+        finishVirtualSurround(QString());
+        return;
+    }
+
+    auto timeout = new QTimer(this);
+    timeout->setSingleShot(true);
+    auto done = [this, timeout](bool found) {
+        timeout->disconnect();
+        timeout->deleteLater();
+        disconnect(Context::instance(), &Context::sinkAdded, timeout, nullptr);
+        if (found) {
+            finishVirtualSurround(QString());
+            return;
+        }
+        qCWarning(PLASMAPA) << "PipeWire did not create" << virtualSurroundSinkName;
+        writeVirtualSurroundConfig(false);
+        finishVirtualSurround(xi18nc("@info:status error message",
+                                     "Virtual surround sound is not available.<nl/>"
+                                     "PipeWire could not create the virtual output device. Its SOFA spatializer plugin may not be installed."));
+    };
+    connect(Context::instance(), &Context::sinkAdded, timeout, [done](Sink *sink) {
+        if (sink->name() == virtualSurroundSinkName) {
+            done(true);
+        }
+    });
+    connect(timeout, &QTimer::timeout, this, [done, hasSink] {
+        done(hasSink());
+    });
+    // Allow for PulseAudioQt's reconnection delay after the restart
+    timeout->start(15s);
+}
+
+void ModuleManager::finishVirtualSurround(const QString &error)
+{
+    m_virtualSurroundBusy = false;
+    m_virtualSurroundError = error;
+    Q_EMIT virtualSurroundChanged();
+}
+
+bool ModuleManager::virtualSurroundBusy() const
+{
+    return m_virtualSurroundBusy;
+}
+
+QString ModuleManager::virtualSurroundError() const
+{
+    return m_virtualSurroundError;
+}
+
+void ModuleManager::clearVirtualSurroundError()
+{
+    if (m_virtualSurroundError.isEmpty()) {
+        return;
+    }
+    m_virtualSurroundError.clear();
+    Q_EMIT virtualSurroundChanged();
+}
 }

